#include <bits/stdc++.h>
using namespace std;
struct Read{int x,y,t;char c;};int dx[]={0,1,0,-1},dy[]={1,0,-1,0};int colors[81][81];vector<Read> reads;string word;long long nodes=0,candidates=0;int maxlen;map<int,pair<int,string>> shifts;
void check(){candidates++;map<pair<int,int>,vector<Read>> groups;for(auto a:reads)groups[{(a.x%2+2)%2,a.y}].push_back(a);vector<pair<int,int>> in,out;for(auto &[q,rs]:groups){sort(rs.begin(),rs.end(),[](auto a,auto b){return tie(a.x,a.t)<tie(b.x,b.t);});for(int j=1;j<(int)rs.size();j++)if(rs[j-1].c==rs[j].c)return;bool b=rs[0].c=='L';if(b)in.push_back(q);if(b^(rs.size()%2))out.push_back(q);}if(in.size()!=2||out.size()!=2||in[0].second!=in[1].second||out[0].second!=out[1].second)return;int d=out[0].second-in[0].second;if(!shifts.count(d))shifts[d]={(int)word.size(),word};}
void dfs(int x,int y,int h,int e){nodes++;int t=word.size();if(t&&x==-2&&y==0&&e==0)check();if(t==maxlen)return;for(int c=0;c<2;c++){if(colors[x+40][y+40]>=0&&colors[x+40][y+40]!=c)continue;int ne=e+(c?-1:1);if(abs(ne)>maxlen-t-1)continue;int nh=(h+(c?3:1))%4,nx=x+dx[nh],ny=y+dy[nh];if(abs(nx+2)+abs(ny)>maxlen-t-1)continue;int old=colors[x+40][y+40];colors[x+40][y+40]=1-c;word+=c?'L':'R';reads.push_back({x,y,t,c?'L':'R'});dfs(nx,ny,nh,ne);reads.pop_back();word.pop_back();colors[x+40][y+40]=old;}}
int main(int argc,char**argv){maxlen=argc>1?stoi(argv[1]):24;memset(colors,-1,sizeof(colors));dfs(0,0,0,0);cout<<"{\"max_length\":"<<maxlen<<",\"nodes\":"<<nodes<<",\"endpoint_candidates\":"<<candidates<<",\"shifts\":[";bool f=true;for(auto &[d,p]:shifts){cout<<(f?"":",")<<"{\"shift\":"<<d<<",\"length\":"<<p.first<<",\"word\":\""<<p.second<<"\"}";f=false;}cout<<"]}\n";}
